<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { api } from '../api/client';import type { DashboardWidget,History } from '../api/types';import TimeSeriesChart from '../components/TimeSeriesChart.vue';const props=defineProps<{widget:DashboardWidget}>();const history=ref<History|null>(null);const series=computed(()=>[{name:props.widget.title||props.widget.metric||'',data:(history.value?.points??[]).flatMap(p=>{const metric=props.widget.metric??'';const v=metric==='vehicle.speed'?p.speed:p.metrics[metric];return typeof v==='number'?[[p.recorded_at,v] as [string,number]]:[]})}]);onMounted(async()=>{if(props.widget.vehicle_id){const start=new Date(Date.now()-(props.widget.time_range_days??1)*86_400_000);history.value=await api<History>(`/vehicles/${props.widget.vehicle_id}/history?start=${encodeURIComponent(start.toISOString())}&max_points=300`)}})
</script>
<template><article class="widget-card"><span class="eyebrow">{{ widget.title||widget.metric }}</span><TimeSeriesChart :series="series" :height="190" /></article></template>
